shboard_share_revoke_events_execution_unique","fields":["executionId"]},{"name":"dashboard_share_revoke_events_version_creation_unique","fields":["shareId","revokedShareRowVersion","shareCreationExecutionId"]}],"foreignKeys":[{"column":"share_id","target":"dashboard_shares","nullable":false,"deferred":false,"external":false,"requiredContractVersion":2},{"column":"actor_id","target":"profiles","nullable":false,"deferred":false,"external":false},{"column":"execution_id","target":"action_executions","nullable":false,"deferred":false,"external":false,"requiredContractVersion":2},{"column":"share_creation_execution_id","target":"action_executions","nullable":false,"deferred":false,"external":false,"requiredContractVersion":2}],"compositeForeignKeys":[{"columns":["share_id","revoked_share_row_version","share_creation_execution_id"],"target":"dashboard_shares","targetColumns":["id","row_version","execution_id"],"deferred":true}],"normalizedChildren":[],"queryFields":["shareId","actorId","executionId","shareCreationExecutionId","createdAt"],"dateField":"createdAt","bodyGuards":[],"appendOnly":true,"bodyFields":["id","shareId","actorId","executionId","shareCreationExecutionId","priorShareRowVersion","revokedShareRowVersion","createdAt","rowVersion"]},{"table":"dashboard_shares","storage":"mixed","bodyColumn":"payload","markerColumn":"workflow_contract_version","markerlessV2Discriminators":[{"path":"senderIdentityId","presence":true},{"path":"recipientIdentityId","presence":true},{"path":"approvedBranchIds","presence":true}],"projectionEqualities":[],"columns":[{"column":"dashboard_id","bodyField":"dashboardId","type":"text","nullable":false,"immutable":true,"queryable":true},{"column":"dashboard_version_id","bodyField":"dashboardVersionId","type":"text","nullable":true,"immutable":true},{"column":"sender_identity_id","bodyField":"senderIdentityId","type":"text","nullable":true,"immutable":true,"queryable":true},{"column":"recipient_identity_id","bodyField":"recipientIdentityId","type":"text","nullable":true,"queryable":true},{"column":"recipient_id","bodyField":"recipientId","type":"text","nullable":true,"queryable":true},{"column":"actor_id","bodyField":"actorId","type":"text","nullable":true,"queryable":true},{"column":"active","bodyField":"active","type":"boolean","nullable":true,"queryable":true},{"column":"status","bodyField":"status","type":"text","nullable":true,"state":true,"queryable":true},{"column":"semantic_key","bodyField":"semanticKey","type":"text","nullable":true,"immutable":true,"queryable":true},{"column":"execution_id","bodyField":"executionId","type":"text","nullable":true,"immutable":true},{"column":"operation_key","bodyField":"operationKey","type":"text","nullable":true,"queryable":true},{"column":"created_at","bodyField":"createdAt","type":"text","nullable":true,"immutable":true,"queryable":true}],"stateField":"status","permittedTransitions":{"active":["revoked"],"revoked":[]},"terminalImmutableFields":{"revoked":["revokedAt"]},"immutableFields":["id","dashboardId","dashboardVersionId","senderIdentityId","recipientIdentityId","recipientId","actorId","approvedBranchIds","classification","verificationDigest","keyVersion","channel","policy","expiresAt","semanticKey","executionId","operationKey","createdAt"],"unique":[{"name":"dashboard_shares_semantic_unique","fields":["semanticKey"]},{"name":"dashboard_shares_revoke_version_creation_unique","fields":["id","rowVersion","executionId"],"referenceKey":true}],"foreignKeys":[{"column":"dashboard_id","target":"dashboards","nullable":false,"deferred":false,"external":false},{"column":"dashboard_version_id","target":"dashboard_versions","nullable":true,"deferred":false,"external":false},{"column":"sender_identity_id","target":"directory_identities","nullable":true,"deferred":false,"external":false},{"column":"recipient_identity_id","target":"directory_identities","nullable":true,"deferred":false,"external":false},{"column":"recipient_id","target":"profiles","nullable":true,"deferred":false,"external":false},{"column":"actor_id","target":"profiles","nullable":true,"deferred":false,"external":false},{"column":"execution_id","target":"action_executions","nullable":true,"deferred":false,"external":false,"requiredContractVersion":2}],"compositeForeignKeys":[{"columns":["workflow_revoke_share_id","workflow_revoke_share_row_version","workflow_revoke_creation_execution_id"],"target":"dashboard_share_revoke_events","targetColumns":["share_id","revoked_share_row_version","share_creation_execution_id"],"deferred":true}],"normalizedChildren":[],"queryFields":["dashboardId","senderIdentityId","recipientIdentityId","recipientId","actorId","status","semanticKey","createdAt"],"ownerField":"senderIdentityId","dateField":"createdAt","bodyGuards":[],"insertStates":["active"],"legacyQuarantineColumn":"pre_migration_revoke_quarantined","appendOnly":false,"bodyFields":["id","dashboardId","dashboardVersionId","senderIdentityId","recipientIdentityId","approvedBranchIds","classification","verificationDigest","keyVersion","channel","policy","status","expiresAt","rowVersion","semanticKey","executionId","createdAt","revokedAt","recipientId","actorId","active","operationKey"]}]$action_provenance_manifest$::jsonb) item;
create temporary table workflow_provenance_digests(complete text,conversation text,snapshot text) on commit drop;
insert into pg_temp.workflow_provenance_digests select
 (select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) from pg_temp.workflow_provenance_predecessor),
 (select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) from pg_temp.workflow_provenance_conversation),
 (select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) from pg_temp.workflow_provenance_snapshot);
update pg_temp.workflow_provenance_predecessor p set definition=c.definition from pg_temp.workflow_provenance_conversation c where p.table_name=c.table_name;
update pg_temp.workflow_provenance_predecessor p set definition=s.definition from pg_temp.workflow_provenance_snapshot s where p.table_name=s.table_name;
create temporary table workflow_provenance_rows(table_name text,id text,body_text text,row_version bigint,original_columns jsonb,primary key(table_name,id)) on commit drop;
create temporary table workflow_provenance_modes(table_oid oid,trigger_name text,enabled "char",primary key(table_oid,trigger_name)) on commit drop;
create or replace function nexus_private.workflow_action_positive_integer(value jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
begin
 if jsonb_typeof(value) is distinct from 'number' then return false; end if;
 return value::text ~ '^[1-9][0-9]*$' and (value #>> '{}')::numeric<=9007199254740991;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;

create or replace function nexus_private.workflow_action_share_body_valid(body jsonb,marker integer) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text; policy jsonb;
begin
 if jsonb_typeof(body) is distinct from 'object' then return false; end if;
 if marker is null then
  if (select count(*) from jsonb_object_keys(body))<>7 or not body ?& array['id','dashboardId','recipientId','actorId','active','operationKey','createdAt'] then return false; end if;
  foreach field in array array['id','dashboardId','recipientId','actorId'] loop
   if jsonb_typeof(body->field) is distinct from 'string' or nexus_private.workflow_utf16_length(body->>field) not between 1 and 300 then return false; end if;
  end loop;
  return jsonb_typeof(body->'active')='boolean' and jsonb_typeof(body->'operationKey')='string' and jsonb_typeof(body->'createdAt')='string';
 end if;
 if marker<>2 or (select count(*) from jsonb_object_keys(body))<>18
  or not body ?& array['id','dashboardId','dashboardVersionId','senderIdentityId','recipientIdentityId','approvedBranchIds','classification','verificationDigest','keyVersion','channel','policy','status','expiresAt','rowVersion','semanticKey','executionId','createdAt','revokedAt'] then return false; end if;
 foreach field in array array['id','dashboardId','dashboardVersionId','senderIdentityId','recipientIdentityId','semanticKey','executionId'] loop
  if not coalesce(nexus_private.workflow_identifier(body->field),false) then return false; end if;
 end loop;
 if jsonb_typeof(body->'approvedBranchIds') is distinct from 'array' then return false; end if;
 if jsonb_array_length(body->'approvedBranchIds')>100
  or exists(select 1 from jsonb_array_elements(body->'approvedBranchIds') item where not nexus_private.workflow_identifier(item))
  or (select count(*) from jsonb_array_elements(body->'approvedBranchIds'))<>(select count(distinct item) from jsonb_array_elements(body->'approvedBranchIds') item)
  or body->'classification' is distinct from '"internal"'::jsonb
  or jsonb_typeof(body->'verificationDigest') is distinct from 'string' or body->>'verificationDigest' !~ '^[a-f0-9]{64}$'
  or not nexus_private.workflow_action_positive_integer(body->'keyVersion') or not nexus_private.workflow_action_positive_integer(body->'rowVersion')
  or jsonb_typeof(body->'channel') is distinct from 'string' or body->>'channel' not in('simulated_email','simulated_slack')
  or jsonb_typeof(body->'status') is distinct from 'string' or body->>'status' not in('active','revoked')
  or not nexus_private.workflow_chat_instant(body->'expiresAt') or not nexus_private.workflow_chat_instant(body->'createdAt') then return false; end if;
 policy:=body->'policy';
 if jsonb_typeof(policy) is distinct from 'object' then return false; end if;
 if (select count(*) from jsonb_object_keys(policy))<>3 or not policy ?& array['id','version','digest']
  or not coalesce(nexus_private.workflow_identifier(policy->'id'),false) or not nexus_private.workflow_action_positive_integer(policy->'version')
  or jsonb_typeof(policy->'digest') is distinct from 'string' or policy->>'digest' !~ '^[a-f0-9]{64}$' then return false; end if;
 return body->'revokedAt'='null'::jsonb or nexus_private.workflow_chat_instant(body->'revokedAt');
end $$;

create or replace function nexus_private.workflow_action_revoke_body_valid(body jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare field text;
begin
 if jsonb_typeof(body) is distinct from 'object' then return false; end if;
 if (select count(*) from jsonb_object_keys(body))<>9 or not body ?& array['id','shareId','actorId','executionId','shareCreationExecutionId','priorShareRowVersion','revokedShareRowVersion','createdAt','rowVersion'] then return false; end if;
 foreach field in array array['id','shareId','actorId','executionId','shareCreationExecutionId'] loop
  if not coalesce(nexus_private.workflow_identifier(body->field),false) then return false; end if;
 end loop;
 foreach field in array array['priorShareRowVersion','revokedShareRowVersion','rowVersion'] loop
  if not nexus_private.workflow_action_positive_integer(body->field) then return false; end if;
 end loop;
 return (body->>'revokedShareRowVersion')::numeric=(body->>'priorShareRowVersion')::numeric+1 and nexus_private.workflow_chat_instant(body->'createdAt');
end $$;

create or replace function nexus_private.workflow_action_revoke_provenance(body jsonb) returns boolean
language plpgsql stable set search_path='' as $$
begin
 return exists(select 1 from public.dashboard_shares s join public.action_executions x on x.id=workflow_action_revoke_provenance.body->>'executionId'
  join public.action_executions c on c.id=workflow_action_revoke_provenance.body->>'shareCreationExecutionId' join public.pending_actions a on a.id=x.action_id
  join public.pending_actions ca on ca.id=c.action_id join public.directory_identities sender on sender.id=s.sender_identity_id
  where s.id=workflow_action_revoke_provenance.body->>'shareId' and s.workflow_contract_version=2 and s.pre_migration_revoke_quarantined=0 and s.status='revoked'
   and s.row_version=(workflow_action_revoke_provenance.body->>'revokedShareRowVersion')::bigint and (workflow_action_revoke_provenance.body->>'revokedShareRowVersion')::numeric=(workflow_action_revoke_provenance.body->>'priorShareRowVersion')::numeric+1
   and s.execution_id=c.id and c.workflow_contract_version=2 and (c.payload->'contractVersion')::text='2' and jsonb_typeof(c.payload->'actorId')='string' and c.outcome='verified_success' and c.payload->>'outcome'='verified_success'
   and c.payload->>'kind'='dashboard_share' and ca.workflow_contract_version=2 and (ca.payload->'contractVersion')::text='2' and ca.actor_id=c.payload->>'actorId' and sender.profile_id=ca.actor_id
   and ca.payload #>> '{payload,kind}'='dashboard_share' and jsonb_typeof(ca.payload #> '{payload,dashboardId}')='string' and ca.payload #>> '{payload,dashboardId}'=s.dashboard_id
   and jsonb_typeof(ca.payload #> '{payload,recipientIdentityId}')='string' and ca.payload #>> '{payload,recipientIdentityId}'=s.recipient_identity_id and ca.payload #>> '{payload,channel}'=s.payload->>'channel'
   and c.payload->>'createdAt'=s.payload->>'createdAt' and nexus_private.workflow_chat_instant(c.payload->'verifiedAt')
   and jsonb_typeof(ca.payload->'targets')='array' and jsonb_typeof(c.payload->'proofs')='array'
   and exists(select 1 from jsonb_array_elements(c.payload->'proofs') p join jsonb_array_elements(ca.payload->'targets') t on p->>'targetId'=t->>'targetId'
    where jsonb_typeof(p)='object' and jsonb_typeof(t)='object' and jsonb_typeof(t->'targetId')='string' and jsonb_typeof(t #> '{expectedEffectRef,id}')='string'
     and t #>> '{expectedEffectRef,table}'='dashboard_shares' and t #>> '{expectedEffectRef,id}'=s.id
     and (select count(*) from jsonb_object_keys(p))=7 and jsonb_typeof(p->'ref')='object'
     and (select count(*) from jsonb_object_keys(p->'ref'))=2 and p #>> '{ref,table}'='dashboard_shares' and jsonb_typeof(p #> '{ref,id}')='string' and p #>> '{ref,id}'=s.id
     and jsonb_typeof(p->'executionId')='string' and p->>'executionId'=c.id and p->>'outcome'='verified_success' and (p->'observedRowVersion')::text='1'
     and coalesce(nexus_private.workflow_identifier(p->'targetId'),false) and nexus_private.workflow_chat_instant(p->'checkedAt')
     and p->'mismatchCodes'='[]'::jsonb)
   and x.workflow_contract_version=2 and (x.payload->'contractVersion')::text='2' and jsonb_typeof(x.payload->'actorId')='string' and x.payload->>'actorId'=workflow_action_revoke_provenance.body->>'actorId' and a.actor_id=workflow_action_revoke_provenance.body->>'actorId'
   and x.payload->>'kind'='dashboard_share_revoke' and a.workflow_contract_version=2 and (a.payload->'contractVersion')::text='2' and a.payload #>> '{payload,kind}'='dashboard_share_revoke'
   and jsonb_typeof(a.payload #> '{payload,shareId}')='string' and a.payload #>> '{payload,shareId}'=s.id and s.payload->>'revokedAt'=workflow_action_revoke_provenance.body->>'createdAt');
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;
end $$;

create or replace function nexus_private.workflow_action_provenance_guard() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_table_name='dashboard_shares' then
  if tg_op='INSERT' then
   if new.pre_migration_revoke_quarantined<>0 then raise exception 'Immutable historical revoke quarantine' using errcode='23514';end if;
  elsif tg_op='UPDATE' then
   if new.pre_migration_revoke_quarantined is distinct from old.pre_migration_revoke_quarantined then raise exception 'Immutable historical revoke quarantine' using errcode='23514';end if;
  end if;
  if not nexus_private.workflow_action_share_body_valid(new.payload,new.workflow_contract_version) then raise exception 'Invalid dashboard share body' using errcode='23514'; end if;
 elsif tg_table_name='dashboard_share_revoke_events' then
  if tg_op='UPDATE' then raise exception 'Append-only dashboard share revoke event' using errcode='23514';end if;
  if not nexus_private.workflow_action_revoke_body_valid(new.body) or not nexus_private.workflow_action_revoke_provenance(new.body) then
   raise exception 'Invalid dashboard share revoke provenance' using errcode='23514';
  end if;
 end if;
 return new;
end $$;
do $forward$
declare d jsonb;c jsonb;f jsonb;u jsonb;item record;step_digest text;installed_digest text;saved_meta text;saved_ledger text;
 colname text;field text;marker text;constraint_name text;typ text;expression text;names text;changed boolean;source_keys smallint[];target_keys smallint[];
begin
 select md5(string_agg(table_name||definition::text,E'\n' order by table_name)) into step_digest from pg_temp.workflow_provenance_manifest;
 for item in select t.oid,t.relowner,n.nspname,t.relname from pg_catalog.pg_class t join pg_catalog.pg_namespace n on n.oid=t.relnamespace
  where (n.nspname='public' and t.relname in('appmeta','action_targets','dashboard_shares','dashboard_share_revoke_events','profiles','pending_actions','action_executions','investigation_cases','directory_identities'))
   or (n.nspname='nexus_private' and t.relname in('workflow_manifest','workflow_projection_migrations'))
  order by case when t.relname='appmeta' then 0 else 1 end,n.nspname,t.relname loop
  if not pg_catalog.pg_has_role(current_user,item.relowner,'USAGE') and not (select rolsuper from pg_catalog.pg_roles where rolname=current_user) then raise exception 'Workflow action provenance requires table ownership' using errcode='42501'; end if;
  execute format('lock table %I.%I in access exclusive mode',item.nspname,item.relname);
 end loop;
 if (select definition_digest from nexus_private.workflow_projection_migrations where id='202610030002_workflow_projection_completeness') is distinct from (select complete from pg_temp.workflow_provenance_digests)
  or (select definition_digest from nexus_private.workflow_projection_migrations where id='202610040001_workflow_conversation_persistence') is distinct from (select conversation from pg_temp.workflow_provenance_digests)
  or (select definition_digest from nexus_private.workflow_projection_migrations where id='202610040002_workflow_snapshot_proof_references') is distinct from (select snapshot from pg_temp.workflow_provenance_digests) then raise exception 'Workflow action provenance requires frozen predecessor ledgers' using errcode='23514'; end if;
 select definition_digest into installed_digest from nexus_private.workflow_projection_migrations where id='202610040003_workflow_action_target_provenance';
 if installed_digest is not null and installed_digest<>step_digest then raise exception 'Workflow action provenance manifest changed without a new schema version' using errcode='23514'; end if;
 if exists(select 1 from pg_temp.workflow_provenance_predecessor p full join nexus_private.workflow_manifest m using(table_name)
  left join pg_temp.workflow_provenance_manifest a using(table_name)
  where m.table_name is null or (p.table_name is null and (installed_digest is null or a.table_name is null))
   or m.definition is distinct from case when installed_digest is not null and a.table_name is not null then a.definition else p.definition end) then raise exception 'Workflow action provenance preceding manifest does not match its ledger' using errcode='23514'; end if;
 if exists(select 1 from (values('action_targets'),('dashboard_shares')) required_table(table_name) cross join (values('workflow_guard'),('nexus_revision')) required(trigger_name)
  left join pg_catalog.pg_trigger t on t.tgrelid=format('public.%I',required_table.table_name)::regclass and t.tgname=required.trigger_name
  where t.oid is null or t.tgenabled not in('O','A')) then raise exception 'Workflow action provenance requires active preceding guards' using errcode='23514'; end if;
 if (select workflow_adapter_write from public.appmeta where singleton=1)<>0 then raise exception 'Workflow action provenance found an active adapter write' using errcode='23514'; end if;
 select to_jsonb(a)::text into strict saved_meta from public.appmeta a where singleton=1;
 select coalesce(string_agg(id||':'||definition_digest,E'\n' order by id),'') into saved_ledger from nexus_private.workflow_projection_migrations;
 -- Data validation precedes classification; no legacy approval/receipt is invented.
 if exists(select 1 from public.dashboard_shares where not nexus_private.workflow_action_share_body_valid(payload,workflow_contract_version) or payload->>'id' is distinct from id
  or (workflow_contract_version=2 and payload->>'rowVersion' is distinct from row_version::text)) then raise exception 'Workflow action provenance contains incompatible historical share' using errcode='23514'; end if;
 for d in select case when installed_digest is null then p.definition else n.definition end
  from pg_temp.workflow_provenance_predecessor p join pg_temp.workflow_provenance_manifest n using(table_name) where p.table_name in('dashboard_shares','action_targets') loop
  execute format('insert into pg_temp.workflow_provenance_rows select %L,id,%I::text,row_version,to_jsonb(t) from public.%I t',d->>'table',d->>'bodyColumn',d->>'table');
  for c in select value from jsonb_array_elements(d->'columns') loop
   execute format('select exists(select 1 from public.%I t where %s to_jsonb(t)->%L is distinct from nexus_private.workflow_value(t.%I,$1))',d->>'table',case when d->>'storage'='mixed' then 'workflow_contract_version=2 and' else '' end,c->>'column',d->>'bodyColumn') into changed using c;
   if changed then raise exception 'Workflow action provenance contains contradictory historical projection' using errcode='23514'; end if;
  end loop;
 end loop;
 if exists(select 1 from public.action_targets t where body->>'entityType' is distinct from body #>> '{ref,table}'
  or (select count(*) from jsonb_array_elements((case when installed_digest is null then (select definition from pg_temp.workflow_provenance_predecessor where table_name='action_targets') else (select definition from pg_temp.workflow_provenance_manifest where table_name='action_targets') end)->'columns') col_obj(value) where col_obj.value ? 'tagField' and nexus_private.workflow_value(t.body,col_obj.value)<>'null'::jsonb)<>1) then raise exception 'Workflow action provenance contains malformed historical source reference' using errcode='23514'; end if;
 if installed_digest is null then
  if to_regclass('public.dashboard_share_revoke_events') is not null then raise exception 'Workflow action provenance cannot adopt an unledgered revoke-event table' using errcode='23514'; end if;
  if exists(select 1 from pg_catalog.pg_trigger t where t.tgrelid in('public.dashboard_shares'::regclass,'public.action_targets'::regclass) and not t.tgisinternal and t.tgenabled<>'D' and t.tgname not in('workflow_guard','workflow_children','nexus_revision')) then raise exception 'Workflow action provenance cannot suspend an unknown application trigger' using errcode='23514'; end if;
